const bg=e=>{while(e){const b=getComputedStyle(e).backgroundColor;if(b!=='rgba(0, 0, 0, 0)'&&!b.endsWith(', 0)'))return b;e=e.parentElement}return 'rgb(255,255,255)'};
const out={};
['.etapa-envio > .step-info','.etapa-analise > .step-info','#aba-documentos > .name','#aba-andamento > .name','label[for="aviso-email"]','label[for="aviso-sms"]','.upload-label > span','.upload-button > span','.apoio-arquivo','.apoio-formulario','label[for="avisos-todos"]','#tipo-documento'].forEach(s=>{const e=document.querySelector(s);if(!e){out[s]=null;return}const c=getComputedStyle(e);const b=bg(e);const l1=L(c.color),l2=L(b);out[s]={fg:c.color,bg:b,ratio:((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2),fs:c.fontSize,fw:c.fontWeight,op:c.opacity,bgImage:getComputedStyle(e.parentElement).backgroundImage.slice(0,80)}});
const ph=getComputedStyle(document.getElementById('tipo-documento'),'::placeholder');out.placeholder=ph.color;
return out}"}

